     // align with a build number.
     public static readonly string ReportFolder =
         Environment.GetEnvironmentVariable("EVAL_REPORT_FOLDER")
             ?? DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");
 }
 ```

