namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:1
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        builder.AddAzureOpenAIChatClient("chat");
        var host = builder.Build();
        try
        {
            return host.Services.GetRequiredService<IChatClient>();
        }
        catch (InvalidOperationException ex)
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration (AddAzureOpenAIChatClient(\"chat\", \"gpt-4o-mini\")) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost populates this at runtime, " +
                "but `dotnet test` runs standalone. Wire one of:\n" +
                "  # Key-based auth (only if the resource has it enabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name.",
                ex);
        }
    }
}
