internal static class ProjectRoot
{
    public static string Find()
    {
        var dir = AppContext.BaseDirectory;
        while (dir != null)
        {
            if (Directory.GetFiles(dir, "*.csproj").Length > 0)
                return dir;
            dir = Directory.GetParent(dir)?.FullName;
        }

        // Fallback: walk from current directory
        dir = Directory.GetCurrentDirectory();
        while (dir != null)
        {
            if (Directory.GetFiles(dir, "*.csproj").Length > 0)
                return dir;
            dir = Directory.GetParent(dir)?.FullName;
        }

        throw new InvalidOperationException("Cannot find project root (no .csproj found in ancestors).");
    }
}

internal static class RepoRoot
{
    public static string Find()
    {
        var dir = ProjectRoot.Find();
        while (dir != null)
        {
            if (Directory.GetFiles(dir, "*.slnx").Length > 0 || Directory.GetFiles(dir, "*.sln").Length > 0)
                return dir;
            dir = Directory.GetParent(dir)?.FullName;
        }

        // Fallback to project root's parent (assumes project is one level under repo)
        return Directory.GetParent(ProjectRoot.Find())?.FullName
            ?? throw new InvalidOperationException("Cannot find repo root.");
    }
}
