internal sealed record TelemetryRecord(
    string AgentName,
    string Model,
    long InputTokens,
    long OutputTokens,
    long LatencyMs,
    decimal CostUsd);

internal static class TelemetryStore
{
    private static readonly List<TelemetryRecord> s_records = new();
    private static readonly object s_lock = new();

    public static void Record(TelemetryRecord record)
    {
        lock (s_lock) { s_records.Add(record); }
    }

    public static void FlushTo(string outDir)
    {
        Directory.CreateDirectory(outDir);
        List<TelemetryRecord> snapshot;
        lock (s_lock) { snapshot = s_records.ToList(); }

        // telemetry.json
        var json = JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(Path.Combine(outDir, "telemetry.json"), json);

        // telemetry.md
        var sb = new StringBuilder();
        sb.AppendLine("# Telemetry capture");
        sb.AppendLine();
        sb.AppendLine("| Agent | Model | Input Tokens | Output Tokens | Latency (ms) | Cost (USD) |");
        sb.AppendLine("|-------|-------|--------------|---------------|--------------|------------|");
        foreach (var r in snapshot)
        {
            sb.AppendLine($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | ${r.CostUsd:F6} |");
        }
        File.WriteAllText(Path.Combine(outDir, "telemetry.md"), sb.ToString());

        Console.WriteLine($"[Telemetry] Wrote {snapshot.Count} records to {outDir}");
    }
}

