internal sealed record ThresholdEntry(string Metric, double? Min, bool HardFail);

internal static class Thresholds
{
    private static readonly Lazy<List<ThresholdEntry>> s_entries = new(() =>
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return new();
        var options = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
            PropertyNameCaseInsensitive = true,
        };
        return JsonSerializer.Deserialize<List<ThresholdEntry>>(File.ReadAllText(path), options) ?? new();
    });

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        foreach (var threshold in s_entries.Value)
        {
            if (threshold.Min == null) continue;

            foreach (var metric in result.Metrics.Values)
            {
                if (metric.Name != threshold.Metric) continue;
                var value = metric switch
                {
                    EvaluationMetric<long> m => (double)m.Value,
                    EvaluationMetric<double> m => m.Value,
                    _ => (double?)null,
                };
                if (value == null) continue;

                if (value < threshold.Min)
                {
                    var msg = $"[Threshold] {scenarioId}: {threshold.Metric}={value:F3} < {threshold.Min:F3}";
                    if (threshold.HardFail)
                        Assert.Fail(msg);
                    else
                        Console.WriteLine(msg);
                }
            }
        }
    }
}

