internal sealed class PriceTable
{
    private readonly Dictionary<string, PriceEntry> _entries;

    private PriceTable(Dictionary<string, PriceEntry> entries) => _entries = entries;

    public static PriceTable Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "prices.json");
        if (!File.Exists(path)) return new(new());
        var options = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
            PropertyNameCaseInsensitive = true,
        };
        var entries = JsonSerializer.Deserialize<Dictionary<string, PriceEntry>>(
            File.ReadAllText(path), options) ?? new();
        return new PriceTable(entries);
    }

    public decimal Cost(string? modelId, long inputTokens, long outputTokens)
    {
        if (modelId == null || !_entries.TryGetValue(modelId, out var entry))
            return 0m;
        return (decimal)(inputTokens / 1000.0 * entry.InputPer1k +
                         outputTokens / 1000.0 * entry.OutputPer1k);
    }
}

internal sealed record PriceEntry(double InputPer1k, double OutputPer1k);
